import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Alert, Box, CircularProgress, Tab, Tabs, Typography } from '@mui/material';
import IndiaComplianceTrack from '../compliance/IndiaComplianceTrack';
import ExportComplianceTrack from '../compliance/ExportComplianceTrack';
import ComplianceReadinessMap from '../compliance/ComplianceReadinessMap';
import type { ReadinessGridItem } from '../compliance/ComplianceReadinessGrid';
import ApiService from '../../services/api';

/**
 * Enterprise compliance view — listed-company BRSR/XBRL plus global buyer packs (CDP, CSRD).
 */
const EnterpriseCompliancePage: React.FC = () => {
  const [tab, setTab] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [readinessScore, setReadinessScore] = useState<number | null>(null);
  const [mandates, setMandates] = useState<Array<{ title?: string }>>([]);
  const [gaps, setGaps] = useState<Array<{ message?: string }>>([]);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const intelRes = await ApiService.getEnterpriseIntelligence({ period: 'annual', runAgents: false });
      const data = intelRes?.data || intelRes;
      const compliance = (data?.compliance || {}) as {
        readinessScore?: number | null;
        mandates?: Array<{ title?: string }>;
        gaps?: Array<{ message?: string }>;
      };
      setReadinessScore(
        compliance.readinessScore != null ? Number(compliance.readinessScore) : null
      );
      setMandates(Array.isArray(compliance.mandates) ? compliance.mandates : []);
      setGaps(Array.isArray(compliance.gaps) ? compliance.gaps : []);
    } catch {
      setError('Could not load compliance readiness summary.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const indiaItems: ReadinessGridItem[] = useMemo(() => {
    const base: ReadinessGridItem[] = [
      {
        key: 'brsr',
        label: 'BRSR / XBRL',
        href: '/enterprise/compliance',
        score: readinessScore,
        status: (readinessScore ?? 0) >= 75 ? 'ready' : 'gap',
        threshold: 75,
      },
      {
        key: 'iso',
        label: 'ISO inventory prep',
        href: '/enterprise/carbon-footprint',
        score: readinessScore != null ? Math.max(0, readinessScore - 10) : null,
        status: (readinessScore ?? 0) >= 70 ? 'ready' : 'gap',
        threshold: 70,
      },
    ];
    const gapItems = gaps.slice(0, 3).map((g, idx) => ({
      key: `gap-${idx}`,
      label: String(g.message || 'Compliance gap').slice(0, 80),
      href: '/enterprise/reporting',
      score: 20,
      status: 'gap',
      threshold: 75,
    }));
    return [...base, ...gapItems];
  }, [readinessScore, gaps]);

  const exportItems: ReadinessGridItem[] = useMemo(() => ([
    {
      key: 'cdp',
      label: 'CDP buyer pack',
      href: '/enterprise/compliance',
      score: readinessScore != null ? Math.max(0, readinessScore - 15) : null,
      status: (readinessScore ?? 0) >= 80 ? 'ready' : 'gap',
      threshold: 75,
    },
    {
      key: 'csrd',
      label: 'CSRD supplier pack',
      href: '/enterprise/compliance',
      score: readinessScore != null ? Math.max(0, readinessScore - 20) : null,
      status: (readinessScore ?? 0) >= 80 ? 'ready' : 'gap',
      threshold: 75,
    },
    {
      key: 'sbti',
      label: 'SBTi readiness',
      href: '/enterprise/carbon-footprint?section=results',
      score: readinessScore != null ? Math.max(0, readinessScore - 25) : null,
      status: 'gap',
      threshold: 75,
    },
  ]), [readinessScore]);

  const indiaScore = readinessScore;
  const exportScore = readinessScore != null
    ? Math.max(0, Math.round(readinessScore * 0.85))
    : null;

  return (
    <Box>
      <Typography variant="h5" sx={{ fontWeight: 700, mb: 1 }}>
        Enterprise regulatory compliance
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Full SEBI BRSR and XBRL for listed entities, plus CDP, CSRD, and buyer disclosure packs.
        Filing fields sync from your enterprise profile (CIN, listing status, stock exchange).
      </Typography>

      {loading ? (
        <Box sx={{ py: 3, display: 'flex', justifyContent: 'center' }}>
          <CircularProgress size={28} />
        </Box>
      ) : (
        <ComplianceReadinessMap
          indiaItems={indiaItems}
          exportItems={exportItems}
          exportVisible
          indiaScore={indiaScore}
          exportScore={exportScore}
          overallScore={readinessScore}
        />
      )}

      {error ? (
        <Alert severity="warning" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      ) : null}

      {mandates.length > 0 ? (
        <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 2 }}>
          Active mandates: {mandates.map((m) => m.title).filter(Boolean).join(' · ')}
        </Typography>
      ) : null}

      <Tabs value={tab} onChange={(_, value) => setTab(value)} sx={{ mb: 2 }}>
        <Tab label="India — BRSR & XBRL" />
        <Tab label="Global — CDP & buyer packs" />
      </Tabs>
      {tab === 0 ? <IndiaComplianceTrack variant="enterprise" /> : <ExportComplianceTrack variant="enterprise" />}
    </Box>
  );
};

export default EnterpriseCompliancePage;
