import React, { useCallback, useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import ApiService from '../services/api';
import RouteLoadingGate from './RouteLoadingGate';
import { useRegistration } from '../context/RegistrationContext';

interface RequireEnterpriseProps {
  children: React.ReactNode;
}

const RequireEnterprise: React.FC<RequireEnterpriseProps> = ({ children }) => {
  const navigate = useNavigate();
  const { logout } = useRegistration();
  const [loading, setLoading] = useState(true);
  const [hasProfile, setHasProfile] = useState(false);
  const [verificationFailed, setVerificationFailed] = useState(false);

  const checkStatus = useCallback(async () => {
    setVerificationFailed(false);
    try {
      const response = await ApiService.getEnterpriseProfile();
      if (response?.data) {
        setHasProfile(true);
      } else {
        navigate('/enterprise/registration');
      }
    } catch (error: unknown) {
      const err = error as { message?: string; response?: { status?: number }; status?: number };
      const message = String(err?.message || '').toLowerCase();
      const status = err?.response?.status ?? err?.status;

      if (message.includes('not found') || status === 404) {
        navigate('/enterprise/registration');
      } else if (status === 401) {
        // Token invalid/expired — sign out.
        logout({ redirectTo: '/login' });
      } else if (status === 403) {
        // Authenticated non-enterprise user: deny without destroying MSME session (DEEP-BUG-043).
        navigate('/dashboard', { replace: true });
      } else {
        setHasProfile(false);
        setVerificationFailed(true);
      }
    } finally {
      setLoading(false);
    }
  }, [navigate, logout]);

  useEffect(() => {
    checkStatus();
  }, [checkStatus]);

  if (loading) {
    return <RouteLoadingGate message="Checking enterprise profile…" minHeight="400px" />;
  }

  if (verificationFailed) {
    return (
      <div style={{ padding: '2rem', maxWidth: 480, margin: '0 auto', textAlign: 'center' }}>
        <p>We could not verify your enterprise profile. Please try again in a moment.</p>
        <button type="button" onClick={() => { setLoading(true); checkStatus(); }}>
          Retry
        </button>
      </div>
    );
  }

  return hasProfile ? <>{children}</> : null;
};

export default RequireEnterprise;
