import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  LinearProgress,
  List,
  ListItem,
  ListItemText,
  Stack,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import CompareArrows from '@mui/icons-material/CompareArrows';
import ApiService from '../../services/api';

type BridgeAction = {
  id: string;
  title: string;
  description?: string;
  path: string;
  priority?: string;
  bridgeType?: string;
};

type ParityGap = {
  id: string;
  title: string;
  message: string;
  severity?: string;
  category?: string;
};

type SegmentParityData = {
  segment?: string;
  parityScore?: number;
  summary?: string;
  highSeverityGapCount?: number;
  gaps?: ParityGap[];
  bridgeActions?: BridgeAction[];
};

type SegmentParityPanelProps = {
  variant?: 'msme' | 'enterprise';
  compact?: boolean;
};

const priorityColor = (priority?: string): 'error' | 'warning' | 'default' => {
  if (priority === 'high') return 'error';
  if (priority === 'medium') return 'warning';
  return 'default';
};

const SegmentParityPanel: React.FC<SegmentParityPanelProps> = ({ variant, compact = false }) => {
  const [data, setData] = useState<SegmentParityData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getSegmentParityAnalysis();
      setData((res?.data || null) as SegmentParityData | null);
    } catch (e) {
      setData(null);
      setError(e instanceof Error ? e.message : 'Unable to load workspace parity analysis');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  if (loading) {
    return (
      <Card variant="outlined">
        <CardContent sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          <CircularProgress size={24} />
          <Typography variant="body2" color="text.secondary">
            Analyzing workspace gaps…
          </Typography>
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Alert
        severity="warning"
        action={(
          <Button color="inherit" size="small" onClick={load}>
            Retry
          </Button>
        )}
      >
        {error}
      </Alert>
    );
  }

  if (!data) {
    return null;
  }

  const score = data.parityScore ?? 0;
  const otherLabel = (variant || data.segment) === 'enterprise' ? 'MSME' : 'Enterprise';

  return (
    <Card variant="outlined">
      <CardContent>
        <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1 }}>
          <CompareArrows color="primary" fontSize="small" />
          <Typography variant="h6" sx={{ fontWeight: 700 }}>
            Workspace parity advisor
          </Typography>
          <Chip
            size="small"
            label={`${score}% aligned`}
            color={score >= 75 ? 'success' : score >= 50 ? 'warning' : 'default'}
          />
        </Stack>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          AI agent comparing your {(variant || data.segment) === 'enterprise' ? 'enterprise' : 'MSME'} workspace
          with {otherLabel} capabilities and recommending bridging actions.
        </Typography>

        {!compact && (
          <>
            <LinearProgress
              variant="determinate"
              value={score}
              sx={{ mb: 2, height: 8, borderRadius: 1 }}
              color={score >= 75 ? 'success' : score >= 50 ? 'warning' : 'primary'}
            />
            {data.summary && (
              <Alert severity={data.highSeverityGapCount ? 'info' : 'success'} sx={{ mb: 2 }}>
                {data.summary}
              </Alert>
            )}
          </>
        )}

        {(data.bridgeActions || []).length > 0 && (
          <Box sx={{ mb: compact ? 0 : 2 }}>
            <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1 }}>
              Bridging actions
            </Typography>
            <List dense disablePadding>
              {(data.bridgeActions || []).slice(0, compact ? 3 : 6).map((action) => (
                <ListItem
                  key={action.id}
                  disableGutters
                  secondaryAction={(
                    <Button
                      component={RouterLink}
                      to={action.path}
                      size="small"
                      variant="outlined"
                    >
                      Open
                    </Button>
                  )}
                >
                  <ListItemText
                    primary={(
                      <Stack direction="row" spacing={1} alignItems="center">
                        <Typography variant="body2" fontWeight={600}>
                          {action.title}
                        </Typography>
                        {action.priority && (
                          <Chip size="small" label={action.priority} color={priorityColor(action.priority)} />
                        )}
                      </Stack>
                    )}
                    secondary={action.description}
                  />
                </ListItem>
              ))}
            </List>
          </Box>
        )}

        {!compact && (data.gaps || []).length > 0 && (
          <Box>
            <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1 }}>
              Detected gaps ({data.gaps?.length})
            </Typography>
            <Stack spacing={1}>
              {(data.gaps || []).slice(0, 4).map((gap) => (
                <Alert key={gap.id} severity={gap.severity === 'high' ? 'warning' : 'info'}>
                  <Typography variant="body2" fontWeight={600}>
                    {gap.title}
                  </Typography>
                  <Typography variant="caption">{gap.message}</Typography>
                </Alert>
              ))}
            </Stack>
          </Box>
        )}

        <Button size="small" onClick={load} sx={{ mt: 2 }}>
          Refresh analysis
        </Button>
      </CardContent>
    </Card>
  );
};

export default SegmentParityPanel;
