import React, { Suspense } from 'react';
import { Navigate, Route, Routes } from 'react-router-dom';
import ProtectedRoute from '../ProtectedRoute';
import RequireEnterprise from '../RequireEnterprise';
import RouteLoadingGate from '../RouteLoadingGate';
import EnterpriseRegistration from './EnterpriseRegistration';
import EnterpriseDashboard from './EnterpriseDashboard';
import EnterpriseProfileSection from './EnterpriseProfileSection';
import EnterpriseWorkflowPlanner from './EnterpriseWorkflowPlanner';
import EnterpriseCompliancePage from './EnterpriseCompliancePage';
import EnterpriseCarbonFootprint from './EnterpriseCarbonFootprint';
import EnterprisePricingPage from './EnterprisePricingPage';
import DataPrivacy from '../DataPrivacy';
import { SettingsPage } from '../StaticPages';

const ReportingScreen = React.lazy(() => import('../ReportingScreen'));
const DocumentManagement = React.lazy(() => import('../DocumentManagement'));

const EnterpriseOnboardedRoute: React.FC<{ children: React.ReactElement }> = ({ children }) => (
  <ProtectedRoute>
    <RequireEnterprise>{children}</RequireEnterprise>
  </ProtectedRoute>
);

/** Enterprise workspace routes (listed companies and large corporates). */
const EnterpriseAppRoutes: React.FC = () => (
  <Suspense fallback={<RouteLoadingGate message="Loading enterprise workspace…" minHeight="40vh" />}>
    <Routes>
      <Route
        path="registration"
        element={(
          <ProtectedRoute>
            <EnterpriseRegistration />
          </ProtectedRoute>
        )}
      />
      <Route
        path="dashboard"
        element={(
          <EnterpriseOnboardedRoute>
            <EnterpriseDashboard />
          </EnterpriseOnboardedRoute>
        )}
      />
      <Route
        path="profile"
        element={(
          <EnterpriseOnboardedRoute>
            <EnterpriseProfileSection />
          </EnterpriseOnboardedRoute>
        )}
      />
      <Route
        path="workflow"
        element={(
          <EnterpriseOnboardedRoute>
            <EnterpriseWorkflowPlanner />
          </EnterpriseOnboardedRoute>
        )}
      />
      <Route
        path="compliance"
        element={(
          <EnterpriseOnboardedRoute>
            <EnterpriseCompliancePage />
          </EnterpriseOnboardedRoute>
        )}
      />
      <Route
        path="reporting"
        element={(
          <EnterpriseOnboardedRoute>
            <ReportingScreen />
          </EnterpriseOnboardedRoute>
        )}
      />
      <Route
        path="carbon-footprint"
        element={(
          <EnterpriseOnboardedRoute>
            <EnterpriseCarbonFootprint />
          </EnterpriseOnboardedRoute>
        )}
      />
      <Route
        path="data"
        element={(
          <EnterpriseOnboardedRoute>
            <DocumentManagement />
          </EnterpriseOnboardedRoute>
        )}
      />
      <Route
        path="pricing"
        element={(
          <EnterpriseOnboardedRoute>
            <EnterprisePricingPage />
          </EnterpriseOnboardedRoute>
        )}
      />
      <Route
        path="settings"
        element={(
          <EnterpriseOnboardedRoute>
            <SettingsPage variant="enterprise" />
          </EnterpriseOnboardedRoute>
        )}
      />
      <Route
        path="data-privacy"
        element={(
          <EnterpriseOnboardedRoute>
            <DataPrivacy />
          </EnterpriseOnboardedRoute>
        )}
      />
      <Route path="" element={<Navigate to="dashboard" replace />} />
      <Route path="*" element={<Navigate to="dashboard" replace />} />
    </Routes>
  </Suspense>
);

export default EnterpriseAppRoutes;
